<body>
<header><h1>My Bookmarks</h1></header>
<main>
  <div class="card">
    <div class="addrow">
      <input id="url" type="text" placeholder="Paste a link, e.g. https://…" autocomplete="off">
      <button class="btn" id="add">Add</button>
    </div>
    <div id="slot"></div>
  </div>
  <div class="status" id="status"></div>

  <div class="searchbar">
    <input id="search" type="text" placeholder="Search your bookmarks — address, title, description, note">
  </div>
  <div class="filters" id="filters"></div>
  <div class="resultcount" id="count"></div>
  <div class="list" id="list"></div>
</main>

<script>
const KNOWN = {
  "developer.mozilla.org": { title:"MDN Web Docs", desc:"Resources for developers, by developers." },
  "github.com": { title:"GitHub", desc:"Let's build from here — the world's largest developer platform." },
  "en.wikipedia.org": { title:"Wikipedia, the free encyclopedia", desc:"The free encyclopedia anyone can edit." },
  "news.ycombinator.com": { title:"Hacker News", desc:"News and discussion for the tech community." },
  "www.figma.com": { title:"Figma: The Collaborative Interface Design Tool", desc:"Design, prototype, and gather feedback all in one place." }
};
function normalizeUrl(raw){ let s=raw.trim(); if(!s) return null; if(!/^https?:\/\//i.test(s)) s="https://"+s; try{return new URL(s);}catch(e){return null;} }
function fakeFetchInfo(u){
  const host=u.hostname.replace(/^www\./,''); const k=KNOWN[u.hostname]||KNOWN[host]; if(k) return {...k};
  const path=u.pathname.replace(/\/$/,'').split('/').filter(Boolean).pop()||host;
  const pretty=decodeURIComponent(path).replace(/[-_]/g,' ').replace(/\.\w+$/,'');
  return { title: pretty.charAt(0).toUpperCase()+pretty.slice(1)+" — "+host, desc:"" };
}
const FAV_COLORS=["#2f6df6","#e2528b","#12a150","#f59e0b","#8b5cf6","#0891b2","#dc2626"];
function faviconFor(u){ const host=u.hostname.replace(/^www\./,''); let s=0; for(const c of host)s+=c.charCodeAt(0); return {letter:host.charAt(0).toUpperCase(), color:FAV_COLORS[s%FAV_COLORS.length]}; }
function renderNote(txt){
  const esc=s=>s.replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c]));
  const link=s=>esc(s).replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g,'<a href="$2" target="_blank" rel="noopener">$1</a>');
  return txt.split(/\n{2,}/).map(b=>{ const lines=b.split('\n');
    return lines.every(l=>/^\s*-\s+/.test(l)) ? '<ul>'+lines.map(l=>'<li>'+link(l.replace(/^\s*-\s+/,''))+'</li>').join('')+'</ul>'
                                              : '<p>'+lines.map(link).join('<br>')+'</p>'; }).join('');
}
function hl(text, q){ if(!q) return escapeHtml(text); const i=text.toLowerCase().indexOf(q.toLowerCase());
  if(i<0) return escapeHtml(text); return escapeHtml(text.slice(0,i))+'<mark>'+escapeHtml(text.slice(i,i+q.length))+'</mark>'+escapeHtml(text.slice(i+q.length)); }
function escapeHtml(s){ return s.replace(/[&<>]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;'}[c])); }

// seed a few so search/tags are explorable immediately
const bookmarks=[
  { url:"https://developer.mozilla.org/en-US/docs/Web/CSS/grid", fav:faviconFor(new URL("https://developer.mozilla.org")), title:"CSS grid layout — MDN", desc:"A guide to two-dimensional grid layouts in CSS.", note:"", tags:["css","reference","read-later"] },
  { url:"https://news.ycombinator.com/item?id=12345", fav:faviconFor(new URL("https://news.ycombinator.com")), title:"Show HN: A tiny bookmark manager", desc:"News and discussion for the tech community.", note:"- compare with our idea\n- [thread](https://news.ycombinator.com)", tags:["inspiration"] },
  { url:"https://www.figma.com/", fav:faviconFor(new URL("https://www.figma.com")), title:"Figma: The Collaborative Interface Design Tool", desc:"Design, prototype, and gather feedback all in one place.", note:"", tags:["design","tools"] }
];

let query="";
let activeTags=new Set();
const listEl=document.getElementById('list'), statusEl=document.getElementById('status'),
      slot=document.getElementById('slot'), filtersEl=document.getElementById('filters'), countEl=document.getElementById('count');

function allTags(){ const m=new Map(); bookmarks.forEach(b=>b.tags.forEach(t=>m.set(t,(m.get(t)||0)+1))); return [...m.entries()].sort((a,b)=>b[1]-a[1]); }

function matches(b){
  if(activeTags.size){ for(const t of activeTags) if(!b.tags.includes(t)) return false; }
  if(query){ const q=query.toLowerCase();
    const hay=[b.url,b.title,b.desc,b.note].join('\n').toLowerCase();
    if(!hay.includes(q)) return false; }
  return true;
}

function renderFilters(){
  const tags=allTags();
  filtersEl.innerHTML = tags.length ? '<span class="lbl">Tags:</span>' : '';
  tags.forEach(([t,c])=>{
    const el=document.createElement('span'); el.className='tag click'+(activeTags.has(t)?' on':'');
    el.textContent=`${t} (${c})`;
    el.addEventListener('click',()=>{ activeTags.has(t)?activeTags.delete(t):activeTags.add(t); update(); });
    filtersEl.appendChild(el);
  });
  if(activeTags.size){ const clr=document.createElement('span'); clr.className='tag click'; clr.textContent='clear'; clr.style.color='#b91c1c';
    clr.addEventListener('click',()=>{ activeTags.clear(); update(); }); filtersEl.appendChild(clr); }
}

function update(){ renderFilters(); render(); }

function render(){
  const shown=bookmarks.filter(matches);
  countEl.textContent = (query||activeTags.size) ? `${shown.length} of ${bookmarks.length} shown` : `${bookmarks.length} bookmark(s)`;
  if(shown.length===0){
    listEl.innerHTML = (query||activeTags.size)
      ? '<div class="empty"><strong>No matches</strong>Nothing matches your search or the selected tags. Try different words or clear a tag.</div>'
      : '<div class="empty"><strong>No bookmarks yet</strong>Paste a link above to save your first one.</div>';
    return;
  }
  listEl.innerHTML='';
  shown.forEach(b=>{
    const el=document.createElement('div'); el.className='bm';
    const fav=document.createElement('div'); fav.className='fav'; fav.style.background=b.fav.color; fav.textContent=b.fav.letter; el.appendChild(fav);
    const body=document.createElement('div'); body.className='body'; el.appendChild(body);
    body.innerHTML =
      `<p class="title"><a href="${b.url}" target="_blank" rel="noopener">${hl(b.title,query)}</a></p>`+
      (b.desc?`<p class="desc">${hl(b.desc,query)}</p>`:``)+
      (b.note?`<div class="note"><div class="note-label">My note</div><div class="note-body">${renderNote(b.note)}</div></div>`:``)+
      (b.tags.length?`<div class="tagrow"></div>`:``)+
      `<div class="url">${hl(b.url,query)}</div>`+
      `<div class="actions"><button class="edit">Edit details</button></div>`;
    if(b.tags.length){ const tr=body.querySelector('.tagrow');
      b.tags.forEach(t=>{ const s=document.createElement('span'); s.className='tag click'+(activeTags.has(t)?' on':''); s.textContent=t;
        s.addEventListener('click',()=>{ activeTags.has(t)?activeTags.delete(t):activeTags.add(t); update(); }); tr.appendChild(s); }); }
    body.querySelector('.edit').addEventListener('click',()=>openEditor(b, body));
    listEl.appendChild(el);
  });
}

// ---- tag chip input ----
function tagEditor(initial){
  const wrap=document.createElement('div'); wrap.className='taginput';
  const tags=[...initial];
  const input=document.createElement('input'); input.placeholder=tags.length?'add a tag…':'type a tag and press Enter';
  function draw(){ [...wrap.querySelectorAll('.tag')].forEach(n=>n.remove());
    tags.forEach((t,i)=>{ const s=document.createElement('span'); s.className='tag'; s.innerHTML=`${escapeHtml(t)} <span class="x">×</span>`;
      s.querySelector('.x').addEventListener('click',()=>{ tags.splice(i,1); draw(); }); wrap.insertBefore(s,input); }); }
  input.addEventListener('keydown',e=>{
    if(e.key==='Enter'||e.key===','){ e.preventDefault(); const v=input.value.trim().toLowerCase().replace(/,$/,'');
      if(v&&!tags.includes(v)) tags.push(v); input.value=''; draw(); }
    else if(e.key==='Backspace'&&!input.value&&tags.length){ tags.pop(); draw(); } });
  wrap.appendChild(input); draw();
  return { el:wrap, get:()=>[...tags] };
}

// ---- draft / editor (Option C panel) ----
function draftFields(d){
  const wrap=document.createElement('div'); wrap.className='draft';
  wrap.innerHTML=`
    <div class="fetchline" ${d.fetched?'':'style="display:none"'}>✓ Title and description picked up automatically — adjust if needed.</div>
    <div><label>Title</label><input class="d-title" type="text"></div>
    <div><label>Description (the site's summary)</label><textarea class="d-desc"></textarea></div>
    <div><label>Tags</label><div class="tagslot"></div></div>
    <div><label>My note (optional)</label><textarea class="d-note" placeholder="Your own note. Use - for a list, [text](https://…) for a link."></textarea>
      <div class="hint">Preview:</div><div class="previewbox d-prev"></div></div>
    <div class="row"><button class="btn d-save">Save bookmark</button><button class="btn ghost d-cancel">Cancel</button></div>`;
  wrap.querySelector('.d-title').value=d.title||'';
  wrap.querySelector('.d-desc').value=d.desc||'';
  wrap.querySelector('.d-note').value=d.note||'';
  const te=tagEditor(d.tags||[]); wrap.querySelector('.tagslot').appendChild(te.el); wrap._tags=te;
  const prev=wrap.querySelector('.d-prev'), noteEl=wrap.querySelector('.d-note');
  const upd=()=>prev.innerHTML=noteEl.value.trim()?renderNote(noteEl.value):'<span style="color:#9ca3af">Nothing yet</span>';
  noteEl.addEventListener('input',upd); upd();
  return wrap;
}
function readDraft(wrap, base){
  return { url:base.url, fav:base.fav,
    title:wrap.querySelector('.d-title').value.trim()||base.title,
    desc:wrap.querySelector('.d-desc').value.trim(),
    note:wrap.querySelector('.d-note').value.trim(),
    tags:wrap._tags.get() };
}
function openEditor(b, body){
  const wrap=draftFields(b); body.innerHTML=''; body.appendChild(wrap);
  wrap.querySelector('.d-save').textContent='Save changes';
  wrap.querySelector('.d-save').addEventListener('click',()=>{ Object.assign(b, readDraft(wrap,b)); statusEl.textContent="Your changes are saved."; update(); });
  wrap.querySelector('.d-cancel').addEventListener('click',update);
}

// ---- add flow (Option C) ----
const urlEl=document.getElementById('url'), addBtn=document.getElementById('add');
function startAdd(){
  const u=normalizeUrl(urlEl.value); if(!u){ statusEl.textContent="That doesn't look like a valid link yet."; return; }
  addBtn.disabled=true; statusEl.textContent="Fetching page details…";
  setTimeout(()=>{ const info=fakeFetchInfo(u); addBtn.disabled=false;
    const base={ url:u.href, fav:faviconFor(u), title:info.title, desc:info.desc, note:'', tags:[], fetched:true };
    const wrap=draftFields(base); slot.innerHTML=''; slot.appendChild(wrap);
    statusEl.textContent="Review and add tags, then confirm.";
    wrap.querySelector('.d-save').addEventListener('click',()=>{ bookmarks.unshift(readDraft(wrap,base)); urlEl.value=''; slot.innerHTML=''; statusEl.textContent="Saved."; urlEl.focus(); update(); });
    wrap.querySelector('.d-cancel').addEventListener('click',()=>{ slot.innerHTML=''; statusEl.textContent=''; });
    wrap.querySelector('.d-title').focus();
  },550);
}
addBtn.addEventListener('click',startAdd); urlEl.addEventListener('keydown',e=>{if(e.key==='Enter')startAdd();});
document.getElementById('search').addEventListener('input',e=>{ query=e.target.value; render(); });

update();
document.body.setAttribute('data-harness-ready','true');
</script>
</body>
